	open fun resize_loads(n_pollutants: Int) {
		this.stat_n_pollutants = n_pollutants
		if (n_pollutants > 0) {
			var total: Long = this.count().toLong() * n_pollutants.toLong()
			this.stat_total_load!!.assign_ul_T(total, 0.0)
		}
	}

	open fun resize_quality(n_pollutants: Int) {
		this.conc_n_pollutants = n_pollutants
		if (n_pollutants > 0) {
			var total: Long = this.count().toLong() * n_pollutants.toLong()
			this.conc!!.assign_ul_T(total, 0.0)
			this.conc_old!!.assign_ul_T(total, 0.0)
			this.hrt!!.assign_ul_T(this.count().toLong(), 0.0)
			this.user_conc_mass_flux!!.assign_ul_T(total, 0.0)
			this.qual_mass_in!!.assign_ul_T(total, 0.0)
			this.iface_qual_mass!!.assign_ul_T(total, 0.0)
			this.coupling_qual_queue!!.assign_ul_T(total, 0.0)
			this.coupling_qual_inflow!!.assign_ul_T(total, 0.0)
			this.ext_qual_mass!!.assign_ul_T(total, 0.0)
			this.dwf_qual_mass!!.assign_ul_T(total, 0.0)
			this.lid_drain_qual_load!!.assign_ul_T(total, 0.0)
		}
	}

