	open fun save_hyd_state() {
		cpp.Algo.copy_IterT_IterT_IterT__D(this.depth!!.begin(), this.depth!!.end(), this.old_depth!!.begin())
		cpp.Algo.copy_IterT_IterT_IterT__D(this.volume!!.begin(), this.volume!!.end(), this.old_volume!!.begin())
		cpp.Algo.copy_IterT_IterT_IterT__D(this.inflow!!.begin(), this.inflow!!.end(), this.old_inflow!!.begin())
		var i: Long = 0L
		__L1@ while (java.lang.Long.compareUnsigned(i, this.inflow!!.size()) < 0) {
			this.old_net_inflow!!.a!![i.toInt()] = this.inflow!!.a!![i.toInt()] - this.outflow!!.a!![i.toInt()]
			i++
		}
	}

	open fun save_lat_qual_state() {
		cpp.Algo.copy_IterT_IterT_IterT__D(this.lat_flow!!.begin(), this.lat_flow!!.end(), this.old_lat_flow!!.begin())
		cpp.Algo.copy_IterT_IterT_IterT__D(this.conc!!.begin(), this.conc!!.end(), this.conc_old!!.begin())
	}

	open fun reset_state() {
		var n: Long = this.depth!!.size()
		var i: Long = 0L
		__L1@ while (java.lang.Long.compareUnsigned(i, n) < 0) {
			this.depth!!.a!![i.toInt()] = this.init_depth!!.a!![i.toInt()]
			this.old_depth!!.a!![i.toInt()] = this.init_depth!!.a!![i.toInt()]
			this.head!!.a!![i.toInt()] = this.invert_elev!!.a!![i.toInt()] + this.init_depth!!.a!![i.toInt()]
			i++
		}
		cpp.Algo.fill_IterT_IterT_T__D(this.volume!!.begin(), this.volume!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.old_volume!!.begin(), this.old_volume!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.lat_flow!!.begin(), this.lat_flow!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.inflow!!.begin(), this.inflow!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.outflow!!.begin(), this.outflow!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.overflow!!.begin(), this.overflow!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.losses!!.begin(), this.losses!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.old_net_inflow!!.begin(), this.old_net_inflow!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.old_lat_flow!!.begin(), this.old_lat_flow!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.old_inflow!!.begin(), this.old_inflow!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.coupling_inflow!!.begin(), this.coupling_inflow!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.coupling_volume!!.begin(), this.coupling_volume!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.coupling_queue!!.begin(), this.coupling_queue!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.coupling_qual_queue!!.begin(), this.coupling_qual_queue!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.coupling_qual_inflow!!.begin(), this.coupling_qual_inflow!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.coupling_age_vol_queue!!.begin(), this.coupling_age_vol_queue!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.coupling_temp_vol_queue!!.begin(), this.coupling_temp_vol_queue!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.coupling_age_vol_inflow!!.begin(), this.coupling_age_vol_inflow!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.coupling_temp_vol_inflow!!.begin(), this.coupling_temp_vol_inflow!!.end(), 0.0)
		this.clearInflowSources()
		cpp.Algo.fill_IterT_IterT_T__D(this.conc!!.begin(), this.conc!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.conc_old!!.begin(), this.conc_old!!.end(), 0.0)
	}

	open fun clearInflowSources() {
		cpp.Algo.fill_IterT_IterT_T__D(this.ext_inflow!!.begin(), this.ext_inflow!!.end(), 0.0)
